import 'package:family_veda/models/doctor_summary.dart';
import 'package:family_veda/models/family_dashboard.dart';
import 'package:family_veda/models/member.dart';
import 'package:family_veda/providers/active_member_provider.dart';
import 'package:family_veda/providers/family_dashboard_role_provider.dart';
import 'package:family_veda/providers/family_portal_provider.dart';
import 'package:family_veda/providers/members_provider.dart';
import 'package:family_veda/screens/appointments/book_appointment_screen.dart';
import 'package:flutter/material.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';
import 'package:flutter_test/flutter_test.dart';

void main() {
  const selfMember = Member(
    id: 'm-1',
    displayName: 'Kamal Perera',
    relationshipLabel: 'Head',
  );

  testWidgets('BookAppointmentScreen shows Family Head guidance and Choose Doctor button when no doctor', (tester) async {
    await tester.pumpWidget(
      ProviderScope(
        overrides: [
          membersProvider.overrideWith((ref) => Future.value([selfMember])),
          activeMemberProvider.overrideWith((ref) => 'm-1'),
          isFamilyHeadProvider.overrideWith((ref) => Future.value(true)),
          familyDashboardProvider.overrideWith(
            (ref) => Future.value(
              const FamilyDashboard(
                role: 'Head',
                familyId: 'fam-1',
                familyName: 'Perera Family',
                memberCount: 1,
                minorCount: 0,
                openCases: 0,
                approvedGuidanceCount: 0,
                unreadNotifications: 0,
                familyDoctor: null,
              ),
            ),
          ),
        ],
        child: const MaterialApp(
          home: BookAppointmentScreen(),
        ),
      ),
    );

    await tester.pumpAndSettle();

    expect(find.text('Book appointment'), findsNWidgets(2)); // App bar + Hero title
    expect(find.text('CLINICAL CARE'), findsOneWidget);
    expect(find.text('No family doctor assigned yet'), findsOneWidget);
    expect(find.text('Choose Family Doctor'), findsOneWidget);
  });

  testWidgets('BookAppointmentScreen shows Adult Member guidance without choose doctor button when no doctor', (tester) async {
    await tester.pumpWidget(
      ProviderScope(
        overrides: [
          membersProvider.overrideWith((ref) => Future.value([selfMember])),
          activeMemberProvider.overrideWith((ref) => 'm-1'),
          isFamilyHeadProvider.overrideWith((ref) => Future.value(false)),
          familyDashboardProvider.overrideWith(
            (ref) => Future.value(
              const FamilyDashboard(
                role: 'AdultMember',
                familyId: 'fam-1',
                familyName: 'Perera Family',
                memberCount: 2,
                minorCount: 0,
                openCases: 0,
                approvedGuidanceCount: 0,
                unreadNotifications: 0,
                familyDoctor: null,
              ),
            ),
          ),
        ],
        child: const MaterialApp(
          home: BookAppointmentScreen(),
        ),
      ),
    );

    await tester.pumpAndSettle();

    expect(find.text('No family doctor assigned'), findsOneWidget);
    expect(find.text('Your family has not chosen a doctor yet. Ask your Family Head to assign one.'), findsOneWidget);
    expect(find.text('Choose Family Doctor'), findsNothing);
  });

  testWidgets('BookAppointmentScreen shows assigned doctor card when doctor exists', (tester) async {
    await tester.pumpWidget(
      ProviderScope(
        overrides: [
          membersProvider.overrideWith((ref) => Future.value([selfMember])),
          activeMemberProvider.overrideWith((ref) => 'm-1'),
          isFamilyHeadProvider.overrideWith((ref) => Future.value(true)),
          familyDashboardProvider.overrideWith(
            (ref) => Future.value(
              const FamilyDashboard(
                role: 'Head',
                familyId: 'fam-1',
                familyName: 'Perera Family',
                memberCount: 1,
                minorCount: 0,
                openCases: 0,
                approvedGuidanceCount: 0,
                unreadNotifications: 0,
                familyDoctor: DoctorSummary(
                  id: 'doc-1',
                  displayName: 'Dr. Nimal Silva',
                  specialty: 'Family Medicine',
                ),
              ),
            ),
          ),
        ],
        child: const MaterialApp(
          home: BookAppointmentScreen(),
        ),
      ),
    );

    await tester.pumpAndSettle();

    expect(find.text('Dr. Nimal Silva'), findsOneWidget);
    expect(find.text('Family Medicine'), findsOneWidget);
    expect(find.text('VERIFIED'), findsOneWidget);
  });
}
